import { Menu, MenuItem, Typography } from '@mui/material'
import { useMemo, useSyncExternalStore, type MouseEvent } from 'react'
import { actionsForContext, diagramContext } from '../../data/action_context'
import { dialogService } from '../../services/dialog_service'
import type { DiagramViewService } from '../../services/diagrams/diagram_view_service'
import { useActions } from '../hooks/use_actions'

interface DiagramItemMenuProps {
    service: Pick<DiagramViewService,
        'closeItemMenu'
        | 'getMenuSnapshot'
        | 'getSavedChildren'
        | 'navigateToSavedDiagram'
        | 'openChildPopup'
        | 'subscribeMenu'>
}

function reportNavigationFailure(error: unknown) {
    dialogService.error(error, { fallbackMessage: 'Diagram navigation failed' })
}

/** Item actions and saved child diagrams, subscribed independently from the diagram surface. */
export function DiagramItemMenu({ service }: DiagramItemMenuProps) {
    const menu = useSyncExternalStore(service.subscribeMenu, service.getMenuSnapshot, service.getMenuSnapshot)
    const { actions } = useActions()
    const selectedContext = useMemo(() => menu
        ? diagramContext('child', menu.diagramId, menu.itemId, menu.itemLabel)
        : null, [menu])
    const childActions = useMemo(
        () => selectedContext ? actionsForContext(actions, selectedContext) : [],
        [actions, selectedContext],
    )
    const savedChildren = menu ? service.getSavedChildren(menu.diagramId, menu.itemId) : []
    const diagramTitle = (record: (typeof savedChildren)[number]) => {
        const label = actions.find(({ id }) => id === record.actionId)?.label ?? record.label

        return record.createdAt ? `${label} - ${new Date(record.createdAt).toLocaleString()}` : label
    }
    const handleClose = () => service.closeItemMenu()
    const handleClick = (event: MouseEvent<HTMLElement>) => {
        const item = (event.target as Element).closest<HTMLElement>('[data-diagram-menu-kind]')
        const kind = item?.dataset.diagramMenuKind
        const id = item?.dataset.diagramMenuId
        if (!kind || !id) return
        if (kind === 'action') {
            service.openChildPopup(id)
            return
        }
        void service.navigateToSavedDiagram(id).catch(reportNavigationFailure)
    }

    return (
        <Menu
            anchorPosition={menu ? { left: menu.left, top: menu.top } : undefined}
            anchorReference="anchorPosition"
            onClick={handleClick}
            onClose={handleClose}
            open={!!menu}
        >
            <Typography color="custom.text3" sx={{ px: 2, py: 0.75 }} variant="overline">Actions</Typography>
            {childActions.length > 0 ? childActions.map((action) => (
                <MenuItem data-diagram-menu-id={action.id} data-diagram-menu-kind="action" key={action.id}>{action.label}</MenuItem>
            )) : <MenuItem disabled>No child actions</MenuItem>}
            <Typography color="custom.text3" sx={{ px: 2, py: 0.75 }} variant="overline">Saved diagrams</Typography>
            {savedChildren.length > 0 ? savedChildren.map((record) => (
                <MenuItem data-diagram-menu-id={record.id} data-diagram-menu-kind="saved" key={record.id}>
                    {diagramTitle(record)}
                </MenuItem>
            )) : <MenuItem disabled>No saved diagrams</MenuItem>}
        </Menu>
    )
}

import { useSyncExternalStore } from 'react'
import type { DiagramViewService } from '../../services/diagrams/diagram_view_service'
import { ActionPopup } from '../actions/run/popup/action_popup'

interface DiagramActionPopupProps {
    service: Pick<DiagramViewService, 'closePopup' | 'getPopupSnapshot' | 'subscribePopup'>
}

/** Active diagram action popup, subscribed independently from the diagram surface. */
export function DiagramActionPopup({ service }: DiagramActionPopupProps) {
    const popup = useSyncExternalStore(service.subscribePopup, service.getPopupSnapshot, service.getPopupSnapshot)
    const handleClose = () => service.closePopup()
    if (!popup) return null

    return (
        <ActionPopup
            anchorElement={popup.anchorElement}
            context={popup.context}
            draggable
            initialActionId={popup.initialActionId}
            onClose={handleClose}
        />
    )
}
